components.css:
.research-areas-page { width: var(--shell); margin: 0 auto; padding-bottom: var(--space-page); }
.areas-masthead { padding: clamp(40px, 5vw, 72px) 0 clamp(32px, 4vw, 52px); }
.areas-masthead h1 { margin: 0; font-size: clamp(38px, 4.8vw, 66px); font-weight: 600; letter-spacing: -.035em; line-height: 1.1; }
.areas-masthead > p { max-width: 66ch; margin: 20px 0 0; color: var(--ink-soft); font-size: clamp(18px, 1.5vw, 20px); line-height: 1.6; }
.areas-guide { border-top: 1px solid var(--ink); }
.areas-field { border-bottom: 1px solid var(--rule-strong); }
.areas-field summary { display: grid; grid-template-columns: minmax(0, 1fr) 28px; align-items: start; gap: 24px; padding: 26px 0; list-style: none; cursor: pointer; }
.areas-field summary::-webkit-details-marker { display: none; }
.areas-field summary::marker { content: ""; }
.areas-field summary h2 { max-width: 35ch; margin: 0; font-size: clamp(25px, 2.7vw, 36px); font-weight: 500; line-height: 1.2; letter-spacing: -.025em; }
.areas-field summary p { max-width: 73ch; margin: 10px 0 0; color: var(--ink-soft); font-size: 16px; line-height: 1.6; }
.areas-field summary:hover h2 { color: var(--red); }
.areas-disclosure { display: flex; align-items: center; justify-content: center; width: 28px; height: 28px; margin-top: 3px; color: var(--red); }
.areas-disclosure svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.5; }
.areas-disclosure-vertical { transform-origin: center; transition: transform var(--dur-2) var(--ease-out); }
.areas-field[open] .areas-disclosure-vertical { transform: rotate(90deg); }
.areas-field-body { display: grid; grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr); gap: 26px 48px; margin-left: clamp(0px, 8vw, 120px); padding: 6px 52px 32px 0; }
.areas-field-body h3 { margin: 0 0 14px; color: var(--slate); font-family: var(--sans); font-size: 14px; font-weight: 600; line-height: 1.5; letter-spacing: 0; }
.areas-field-body ul { margin: 0; padding: 0; list-style: none; }
.areas-questions li { max-width: 45ch; color: var(--ink); font-size: 18px; line-height: 1.6; }
.areas-questions li + li { margin-top: 12px; }
.areas-evidence li { color: var(--ink-soft); font-size: 16px; line-height: 1.6; }
.areas-evidence li + li { margin-top: 10px; }
.areas-publications { grid-column: 1 / -1; display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 24px; padding-top: 18px; border-top: 1px solid var(--rule); }
.areas-publications > p { margin: 0; color: var(--slate); font-size: 14px; line-height: 1.6; }
.areas-link { display: inline-flex; align-items: center; gap: 10px; min-height: 44px; padding: 7px 0; color: var(--red); font-size: 15px; font-weight: 600; line-height: 1.45; text-decoration: underline; text-underline-offset: 5px; }
.areas-link svg { width: 16px; height: 16px; flex: 0 0 16px; }
.areas-link:hover { color: var(--red-dark); text-decoration-thickness: 2px; }
.areas-footer { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 8px 32px; padding-top: 28px; }
.areas-footer > p { margin: 0; color: var(--ink-soft); font-size: 17px; line-height: 1.6; }
@media (max-width: 760px) {
  .areas-field-body { grid-template-columns: minmax(0, 1fr); gap: 24px; margin-left: 0; }
  .areas-publications { grid-column: 1; }
}
@media (max-width: 640px) {
  .areas-masthead { padding-top: 32px; }
  .areas-masthead h1 { font-size: clamp(35px, 8.6vw, 49px); }
  .areas-field summary { gap: 16px; padding: 24px 0; }
  .areas-field summary h2 { font-size: 26px; }
  .areas-field-body { padding-right: 0; }
  .areas-publications { gap: 0 20px; }
}

/* One finite Canada–Europe drawing moment; compact release and upcoming topics. */
.home-masthead { width: var(--shell); margin: 0 auto; padding: clamp(36px, 5vw, 72px) 0 48px; display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr); align-items: center; gap: clamp(28px, 5vw, 72px); }
.home-introduction h1 { margin: 0; font-size: clamp(58px, 6.6vw, 96px); font-weight: 650; letter-spacing: -.04em; line-height: 1; }
.home-introduction h1 > span { display: block; }
.home-title-stop { color: var(--red); }
.home-introduction > p { max-width: 40ch; margin: 24px 0 0; color: var(--ink-soft); font-size: 20px; line-height: 1.6; }
.home-masthead-actions { margin-top: 28px; display: flex; flex-wrap: wrap; align-items: center; gap: 12px 24px; }
.home-masthead-actions .button-primary { font-size: 16px; }
.home-masthead-actions .text-link { font-size: 15px; color: var(--ink); border-color: var(--rule-strong); }
.home-connections { position: relative; min-width: 0; background: var(--soft-black); overflow: hidden; }
.home-connections svg { width: 100%; height: auto; min-height: 260px; }
.home-connections image { opacity: .7; }
.home-connection-base path, .home-connection-drawing path { fill: none; stroke-width: 1.5; }
.home-connection-base path { stroke: rgba(255, 255, 255, .18); }
.home-connection-drawing path { stroke: #d398a4; stroke-dasharray: 1; stroke-dashoffset: 0; }
.home-connection-node { fill: #f6e7eb; stroke: var(--soft-black); stroke-width: 2; }
.home-connection-labels { display: flex; justify-content: space-between; gap: 16px; padding: 0 24px 20px; color: var(--on-dark); font-size: 14px; }
.home-issue { width: var(--shell); margin: 0 auto; padding: 32px 0 40px; display: grid; grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr); gap: clamp(32px, 5vw, 72px); border-top: 1px solid var(--ink); }
.home-release, .home-upcoming { min-width: 0; }
.home-release > h2, .home-upcoming > h2 { margin: 0 0 24px; font-size: 24px; font-weight: 600; letter-spacing: -.02em; }
.home-lead-publication { display: flex; gap: 24px; align-items: flex-start; }
.home-publication-cover { flex: 0 0 150px; display: block; box-shadow: 0 10px 24px -14px rgba(0, 0, 0, .4); transition: transform var(--dur-2) var(--ease-out); }
.home-publication-cover img { display: block; width: 100%; height: auto; }
.home-publication-cover:hover { transform: translateY(-3px); }
.home-publication-body { flex: 1; min-width: 0; }
.home-publication-meta { display: flex; flex-wrap: wrap; gap: 4px 12px; margin-bottom: 12px; color: var(--slate); font-size: 12px; font-variant-numeric: tabular-nums; }
.home-publication-body h3 { margin: 0; font-size: clamp(22px, 2vw, 28px); font-weight: 550; letter-spacing: -.025em; line-height: 1.25; text-wrap: pretty; }
.home-publication-body h3 a { text-decoration: none; }
.home-publication-body h3 a:hover { text-decoration: underline; color: var(--red); }
.home-publication-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 20px; margin-top: 16px; }
.home-read-link { display: inline-flex; min-height: 44px; align-items: center; gap: 16px; color: var(--red); font-size: 15px; font-weight: 600; text-decoration: none; }
.home-read-link svg { width: 18px; height: 18px; transition: transform var(--dur-2) var(--ease-out); }
.home-read-link:hover { text-decoration: underline; }
.home-read-link:hover svg { transform: translateX(4px); }
.home-pdf-link { display: inline-flex; min-height: 44px; align-items: center; color: var(--ink-soft); font-size: 13px; }
.home-upcoming-list { margin: 0; padding: 0; list-style: none; }
.home-upcoming-list li { display: grid; grid-template-columns: 24px minmax(0, 1fr); gap: 16px; padding: 16px 0; border-top: 1px solid var(--rule); }
.home-upcoming-list li:first-child { padding-top: 0; border-top: 0; }
.home-topic-number { color: var(--slate); font-size: 16px; font-variant-numeric: tabular-nums; }
.home-upcoming-list h3 { margin: 0; max-width: 32ch; font-size: 18px; font-weight: 500; line-height: 1.4; letter-spacing: -.015em; }
.home-topic-status { width: fit-content; display: inline-flex; align-items: center; gap: 6px; margin-bottom: 8px; padding: 3px 8px; background: var(--sky); color: var(--red-dark); font-size: 12px; font-weight: 600; }
.home-topic-status::before { content: ""; width: 5px; height: 5px; background: currentColor; border-radius: 50%; }
.home-upcoming-note { margin: 10px 0 0 40px; color: var(--slate); font-size: 12px; }
.home-explore { width: var(--shell); margin: 0 auto; padding: 0 0 clamp(48px, 6vw, 80px); display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }
.home-explore > a { min-height: 88px; padding: 20px 24px; display: flex; align-items: center; justify-content: space-between; gap: 24px; border: 1px solid var(--rule-strong); color: var(--ink); background: var(--ivory); font-family: var(--display); font-size: clamp(18px, 1.6vw, 23px); font-weight: 550; line-height: 1.3; text-decoration: none; transition: background var(--dur-2) var(--ease-out), border-color var(--dur-2) var(--ease-out); }
.home-explore > a svg { flex: none; width: 22px; height: 22px; color: var(--red); transition: transform var(--dur-2) var(--ease-out); }
.home-explore > a:hover { background: var(--ivory-deep); border-color: var(--ink); }
.home-explore > a:hover svg { transform: translateX(4px); }
@media (prefers-reduced-motion: no-preference) {
  .home-connection-drawing path { animation: home-connect 4.2s var(--ease-out) both; }
  .home-connection-drawing path:nth-child(2) { animation-delay: .2s; }
  .home-connection-drawing path:nth-child(3) { animation-delay: .4s; }
}
@keyframes home-connect { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@media (max-width: 1050px) {
  .home-masthead { gap: 32px; }
  .home-masthead-actions { gap: 8px 20px; }
  .home-issue { grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr); gap: 32px; }
  .home-publication-cover { flex-basis: 110px; }
  .home-lead-publication { gap: 20px; }
}
@media (max-width: 760px) {
  .home-masthead { grid-template-columns: minmax(0, 1fr); padding: 32px 0; gap: 28px; }
  .home-introduction h1 { font-size: clamp(54px, 11vw, 76px); }
  .home-introduction > p { font-size: 18px; margin-top: 20px; }
  .home-masthead-actions { margin-top: 20px; }
  .home-connections svg { min-height: 0; }
  .home-connection-labels { padding: 0 20px 16px; }
  .home-issue { grid-template-columns: minmax(0, 1fr); padding: 28px 0 32px; gap: 32px; }
  .home-release > h2, .home-upcoming > h2 { margin-bottom: 20px; font-size: 23px; }
  .home-publication-cover { flex-basis: 84px; }
  .home-lead-publication { gap: 18px; }
  .home-publication-body h3 { font-size: 22px; }
  .home-publication-meta { font-size: 11.5px; }
  .home-publication-actions { gap: 0 16px; margin-top: 10px; }
  .home-upcoming { padding-top: 28px; border-top: 1px solid var(--rule); }
  .home-upcoming-list h3 { max-width: none; }
  .home-explore { gap: 12px; }
  .home-explore > a { min-height: 96px; padding: 16px; gap: 12px; font-size: 18px; }
}
@media (max-width: 480px) {
  .home-explore { grid-template-columns: minmax(0, 1fr); }
  .home-explore > a { min-height: 76px; }
  .home-introduction h1 { font-size: clamp(50px, 14vw, 64px); }
  .home-publication-cover { flex-basis: 72px; }
  .home-publication-body h3 { font-size: 20px; }
}

